437	                                .content(objectMapper.writeValueAsString(overrideBody(
438	                                        "race-req", ctx.key("race"), ctx.channel,
439	                                        ctx.newsAsset, ctx.newsGrant, 5, T_1020, T_1040))))
440	                        .andReturn().getResponse().getStatus();
441	            });
442	            Future<Integer> revokeFuture = pool.submit(() -> {
443	                ready.countDown();
444	                start.await(5, TimeUnit.SECONDS);
445	                return mvc.perform(post("/api/grants/" + ctx.newsGrant + "/revoke")
446	                                .contentType(MediaType.APPLICATION_JSON)
447	                                .content(objectMapper.writeValueAsString(Map.of("requestId", "race-rv"))))
448	                        .andReturn().getResponse().getStatus();
449	            });
450	            ready.await(5, TimeUnit.SECONDS);
451	            start.countDown();
452	            int createStatus = createFuture.get(30, TimeUnit.SECONDS);
453	            int revokeStatus = revokeFuture.get(30, TimeUnit.SECONDS);
454	
455	            // 撤销本身成功；创建要么 422（撤销先提交），要么 200（创建先提交）
456	            assertThat(revokeStatus).isEqualTo(200);
457	            assertThat(createStatus).isIn(200, 422);
458	
459	            MvcResult detail = getOverride(ctx, "race").andReturn();
460	            if (createStatus == 422) {
461	                // 撤销先提交：插播不存在
462	                assertThat(detail.getResponse().getStatus()).isEqualTo(404);
463	            } else {
464	                // 创建先提交：插播保留 ACTIVE 与原授权关联，但后续播出必须排除该插播
465	                JsonNode json = readJson(detail);
466	                assertThat(detail.getResponse().getStatus()).isEqualTo(200);
467	                assertThat(json.get("status").asText()).isEqualTo("ACTIVE");
468	                assertThat(json.get("grantId").asLong()).isEqualTo(ctx.newsGrant);
469	            }
470	            // 无论提交顺序如何，授权已撤销，10:30 都不能命中 EMERGENCY
471	            playout(ctx, T_1030)
472	                    .andExpect(jsonPath("$.source").value("PROGRAM"))
473	                    .andExpect(jsonPath("$.assetId").value(ctx.movieAsset));
474	        } finally {
475	            pool.shutdownNow();
476	        }
477	    }
478	
479	    // ---------- 测试辅助 ----------
480	
481	    /** 预置上下文：保底素材、普通素材 movie/news/alert、频道及各自全天授权。 */
482	    private final class Ctx {
483	        private final String prefix = "e" + UUID.randomUUID().toString().replace("-", "").substring(0, 10) + "-";
484	        private String channel;
485	        private String fallbackAsset;
486	        private String movieAsset;
487	        private String newsAsset;
488	        private String alertAsset;
489	        private long movieGrant;
490	        private long newsGrant;
491	        private long alertGrant;
492	
493	        private String key(String shortKey) {
494	            return prefix + shortKey;
495	        }
496	    }
497	
498	    private Ctx newContext() throws Exception {
499	        Ctx ctx = new Ctx();
500	        ctx.fallbackAsset = ctx.prefix + "fallback";
501	        ctx.movieAsset = ctx.prefix + "movie";
502	        ctx.newsAsset = ctx.prefix + "news";
503	        ctx.alertAsset = ctx.prefix + "alert";
504	        ctx.channel = ctx.prefix + "ch";
505	
506	        postJson("/api/assets", Map.of("id", ctx.fallbackAsset, "durationMs", 30000))
507	                .andExpect(status().isOk());
508	        postJson("/api/assets", Map.of("id", ctx.movieAsset, "durationMs", 3600000))
509	                .andExpect(status().isOk());
510	        postJson("/api/assets", Map.of("id", ctx.newsAsset, "durationMs", 1800000))
511	                .andExpect(status().isOk());
512	        postJson("/api/assets", Map.of("id", ctx.alertAsset, "durationMs", 900000))
513	                .andExpect(status().isOk());
514	        postJson("/api/channels", Map.of("id", ctx.channel, "fallbackAssetId", ctx.fallbackAsset))
515	                .andExpect(status().isOk());
516	        ctx.movieGrant = createGrant(ctx.channel, ctx.movieAsset, GRANT_FROM, GRANT_TO);
517	        ctx.newsGrant = createGrant(ctx.channel, ctx.newsAsset, GRANT_FROM, GRANT_TO);
518	        ctx.alertGrant = createGrant(ctx.channel, ctx.alertAsset, GRANT_FROM, GRANT_TO);
519	        return ctx;
520	    }
521	
522	    /** 发布一段 10:00-11:00 的 movie 节目，作为插播下层的原节目。 */
523	    private void publishProgram(Ctx ctx, String segmentId, String start, String end) throws Exception {
524	        List<Map<String, Object>> segments = new ArrayList<>();
525	        Map<String, Object> segment = new LinkedHashMap<>();
526	        segment.put("id", ctx.prefix + segmentId);
527	        segment.put("assetId", ctx.movieAsset);
528	        segment.put("start", start);
529	        segment.put("end", end);
530	        segments.add(segment);
531	        Map<String, Object> draftBody = new LinkedHashMap<>();
532	        draftBody.put("requestId", "draft-" + ctx.prefix + segmentId);
533	        draftBody.put("expectedDraftVersion", 0);
534	        draftBody.put("segments", segments);
535	        mvc.perform(put("/api/channels/" + ctx.channel + "/drafts/" + DAY)
536	                        .contentType(MediaType.APPLICATION_JSON)
537	                        .content(objectMapper.writeValueAsString(draftBody)))
538	                .andExpect(status().isOk());
539	        postJson("/api/channels/" + ctx.channel + "/drafts/" + DAY + "/publish",
540	                        Map.of("requestId", "pub-" + ctx.prefix + segmentId,
541	                                "draftVersion", 1, "expectedPublishedVersion", 0))
542	                .andExpect(status().isOk());
543	    }
544	
545	    private long createGrant(String channel, String asset, String from, String to) throws Exception {
546	        MvcResult result = postJson("/api/grants", Map.of(
547	                        "channelId", channel, "assetId", asset,
548	                        "validFrom", from, "validTo", to))
549	                .andExpect(status().isOk())
550	                .andReturn();
551	        return readJson(result).get("id").asLong();
552	    }
553	
554	    private ResultActions createOverride(Ctx ctx, String requestId, String shortKey, String assetId,
555	                                         long grantId, int priority, String start, String end)
556	            throws Exception {
557	        return createOverrideRaw(requestId, ctx.key(shortKey), ctx.channel, assetId,
558	                grantId, priority, start, end);
559	    }
560	
561	    private ResultActions createOverrideRaw(String requestId, String overrideKey, String channelId,
562	                                            String assetId, long grantId, int priority,
563	                                            String start, String end) throws Exception {
564	        return postJson("/api/emergency-overrides",
565	                overrideBody(requestId, overrideKey, channelId, assetId, grantId, priority, start, end));
566	    }
567	
568	    private static Map<String, Object> overrideBody(String requestId, String overrideKey,
569	                                                    String channelId, String assetId, long grantId,
570	                                                    int priority, String start, String end) {
571	        Map<String, Object> body = new LinkedHashMap<>();
572	        body.put("requestId", requestId);
573	        body.put("overrideKey", overrideKey);
574	        body.put("channelId", channelId);
575	        body.put("assetId", assetId);
576	        body.put("grantId", grantId);
577	        body.put("priority", priority);
578	        body.put("start", start);
579	        body.put("end", end);
580	        return body;
581	    }
582	
583	    private ResultActions playout(Ctx ctx, String at) throws Exception {
584	        return mvc.perform(get("/api/channels/" + ctx.channel + "/playout").param("at", at));
585	    }
586	
587	    private ResultActions getOverride(Ctx ctx, String shortKey) throws Exception {
588	        return getOverrideRaw(ctx.key(shortKey));
589	    }
590	
591	    private ResultActions getOverrideRaw(String overrideKey) throws Exception {
592	        return mvc.perform(get("/api/emergency-overrides/" + overrideKey));
593	    }
594	
595	    private ResultActions postJson(String url, Object body) throws Exception {
596	        return mvc.perform(post(url).contentType(MediaType.APPLICATION_JSON)
597	                .content(objectMapper.writeValueAsString(body)));
598	    }
599	
600	    private JsonNode readJson(MvcResult result) throws Exception {
601	        return objectMapper.readTree(result.getResponse().getContentAsString());
602	    }
603	
604	    private interface ThrowingSupplier {
605	        Integer get(int index) throws Exception;
606	    }
607	
608	    private List<Integer> runConcurrently(int threads, ThrowingSupplier action) throws Exception {
609	        ExecutorService pool = Executors.newFixedThreadPool(threads);
610	        CountDownLatch ready = new CountDownLatch(threads);
611	        CountDownLatch start = new CountDownLatch(1);
612	        List<Future<Integer>> futures = new ArrayList<>();
613	        for (int i = 0; i < threads; i++) {
614	            final int index = i;
615	            futures.add(pool.submit(() -> {
616	                ready.countDown();
617	                start.await(5, TimeUnit.SECONDS);
618	                return action.get(index);
619	            }));
620	        }
621	        ready.await(5, TimeUnit.SECONDS);
622	        start.countDown();
623	        List<Integer> results = new ArrayList<>();
624	        for (Future<Integer> future : futures) {
625	            results.add(future.get(30, TimeUnit.SECONDS));
626	        }
627	        pool.shutdownNow();
628	        return results;
629	    }
630	}
